// Sets, relations, and functions mini demo
#include <algorithm>
#include <iostream>
#include <iterator>
#include <map>
#include <set>
#include <string>
#include <vector>

// std::set keeps elements sorted, so the printout is predictable
template <typename C>
std::string show(const C& s) {
    std::string out = "{";
    bool first = true;
    for (int x : s) {
        out += (first ? "" : ", ") + std::to_string(x);
        first = false;
    }
    return out + "}";
}

bool isInjective(const std::map<int, int>& f) {
    std::set<int> seen;
    for (const auto& [x, y] : f) {
        if (!seen.insert(y).second) return false;  // two inputs share an output
    }
    return true;
}

bool isSurjective(const std::map<int, int>& f, const std::set<int>& codomain) {
    std::set<int> image;
    for (const auto& [x, y] : f) image.insert(y);
    return std::includes(image.begin(), image.end(), codomain.begin(), codomain.end());
}

// The relation R is "x <= y"; any other predicate could be tested the same way
bool leq(int x, int y) { return x <= y; }

std::string yesNo(bool b) { return b ? "yes" : "no"; }

int main() {
    const std::set<int> a = {1, 2, 3};
    const std::set<int> b = {3, 4, 5};
    std::set<int> intersection, unionSet, difference;
    std::set_intersection(a.begin(), a.end(), b.begin(), b.end(), std::inserter(intersection, intersection.end()));
    std::set_union(a.begin(), a.end(), b.begin(), b.end(), std::inserter(unionSet, unionSet.end()));
    std::set_difference(a.begin(), a.end(), b.begin(), b.end(), std::inserter(difference, difference.end()));
    std::cout << "A = " << show(a) << ", B = " << show(b) << "\n";
    std::cout << "A intersect B = " << show(intersection) << "\n";
    std::cout << "A union B     = " << show(unionSet) << "\n";
    std::cout << "A minus B     = " << show(difference) << "\n";
    std::cout << "|A union B| = |A| + |B| - |A intersect B| = " << a.size() << " + " << b.size() << " - "
              << intersection.size() << " = " << unionSet.size() << "\n";
    std::cout << "|A x B| = " << a.size() << " * " << b.size() << " = " << a.size() * b.size() << " pairs\n";

    // Each bit of mask decides whether one element is in the subset
    const std::vector<int> elems(a.begin(), a.end());
    std::string subsets;
    for (int mask = 0; mask < (1 << elems.size()); mask++) {
        std::vector<int> sub;
        for (size_t i = 0; i < elems.size(); i++) {
            if (mask & (1 << i)) sub.push_back(elems[i]);
        }
        subsets += (mask ? " " : "") + show(sub);
    }
    std::cout << "P(A) has 2^3 = " << (1 << elems.size()) << " subsets: " << subsets << "\n";

    // The relation <= on A, checked straight from the definitions
    bool reflexive = true, antisymmetric = true, transitive = true;
    for (int x : a) {
        reflexive = reflexive && leq(x, x);
        for (int y : a) {
            if (leq(x, y) && leq(y, x) && x != y) antisymmetric = false;
            for (int z : a) {
                if (leq(x, y) && leq(y, z) && !(leq(x, z))) transitive = false;
            }
        }
    }
    std::cout << "<= on A: reflexive=" << yesNo(reflexive) << " antisymmetric=" << yesNo(antisymmetric)
              << " transitive=" << yesNo(transitive) << " -> partial order\n";

    const std::map<int, int> f = {{1, 10}, {2, 20}, {3, 30}};
    const std::set<int> codomain = {10, 20, 30};
    std::cout << "f = {1->10, 2->20, 3->30}: injective? " << yesNo(isInjective(f)) << ", onto " << show(codomain)
              << "? " << yesNo(isSurjective(f, codomain)) << "\n";
}

