// The Cartesian product A x B: every ordered pair (a, b) with a from A and b from B
#include <algorithm>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

using Pair = std::pair<std::string, std::string>;

// Nested loops: the outer element is always the first coordinate
std::vector<Pair> product(const std::vector<std::string>& a, const std::vector<std::string>& b) {
    std::vector<Pair> result;
    for (const auto& x : a) {
        for (const auto& y : b) result.emplace_back(x, y);
    }
    return result;
}

std::string showPair(const Pair& p) { return "(" + p.first + ", " + p.second + ")"; }

std::string show(const std::vector<Pair>& pairs) {
    std::string out = "{";
    for (size_t i = 0; i < pairs.size(); i++) out += (i ? ", " : "") + showPair(pairs[i]);
    return out + "}";
}

bool contains(const std::vector<Pair>& pairs, const Pair& p) {
    return std::find(pairs.begin(), pairs.end(), p) != pairs.end();
}

int main() {
    const std::vector<std::string> a = {"1", "2", "3"};
    const std::vector<std::string> b = {"x", "y"};
    auto ab = product(a, b);
    auto ba = product(b, a);
    std::cout << "A = {1, 2, 3}, B = {x, y}\n";
    std::cout << "A x B = " << show(ab) << "\n";
    std::cout << "|A x B| = " << ab.size() << " = |A| * |B| = " << a.size() << " * " << b.size() << "\n";
    std::cout << "B x A = " << show(ba) << "\n";
    // Pairs are ordered, so (1, x) and (x, 1) are different objects
    Pair p{"1", "x"};
