import java.util.*;
import java.util.function.IntUnaryOperator;

// Injective (one-to-one): different inputs always give different outputs
public class InjectiveFunctions {
    // Returns null if f is injective on 0..size-1, otherwise the first collision found
    static String findCollision(IntUnaryOperator f, int size, String name) {
        Map<Integer, Integer> firstInput = new HashMap<>(); // output -> input that produced it
        for (int x = 0; x < size; x++) {
            int y = f.applyAsInt(x);
            Integer earlier = firstInput.putIfAbsent(y, x);
            if (earlier != null) return name + "(" + earlier + ") = " + name + "(" + x + ") = " + y;
        }
        return null;
    }

    static void report(String name, String rule, IntUnaryOperator f) {
        StringJoiner values = new StringJoiner(" ");
        for (int x = 0; x < 5; x++) values.add(String.valueOf(f.applyAsInt(x)));
        String collision = findCollision(f, 5, name);
        System.out.println(name + "(x) = " + rule + " on {0..4}: " + values + " -> "
                + (collision == null ? "injective" : "not injective, " + collision));
    }

    // Brute force: try all n^m functions {0..m-1} -> {0..n-1} and count the injective ones
    static void countInjections(int m, int n) {
        int total = (int) Math.pow(n, m), injective = 0;
        for (int code = 0; code < total; code++) {
            Set<Integer> outputs = new HashSet<>();
            int c = code;
            for (int x = 0; x < m; x++) {
                outputs.add(c % n); // digit x of code in base n is f(x)
                c /= n;
            }
            if (outputs.size() == m) injective++;
        }
        long formula = 1; // P(n, m) = n * (n-1) * ... * (n-m+1); it is 0 when m > n
        for (int i = 0; i < m; i++) formula *= Math.max(n - i, 0);
        System.out.println("injections from a " + m + "-set into a " + n + "-set: " + injective + " of " + total
                + " functions (P(" + n + "," + m + ") = " + formula + ")");
    }

    public static void main(String[] args) {
        report("f", "2x+1", x -> 2 * x + 1);
        report("g", "x*x mod 5", x -> x * x % 5);
        countInjections(2, 3);
        countInjections(3, 4);
        countInjections(5, 4); // pigeonhole: 5 inputs cannot fit into 4 distinct outputs
    }
}

