import java.util.*;
import java.util.function.IntUnaryOperator;

// Surjective (onto): every element of the codomain is hit by at least one input
public class SurjectiveFunctions {
    static String show(Set<Integer> s) {
        StringJoiner j = new StringJoiner(", ", "{", "}");
        for (int x : s) j.add(String.valueOf(x));
        return j.toString();
    }

    static void report(String label, IntUnaryOperator f, int domainSize, int codomainSize) {
        Set<Integer> image = new TreeSet<>();
        for (int x = 0; x < domainSize; x++) image.add(f.applyAsInt(x));
        Set<Integer> missed = new TreeSet<>();
        for (int y = 0; y < codomainSize; y++) if (!image.contains(y)) missed.add(y);
        System.out.println(label + ": image " + show(image) + " -> "
                + (missed.isEmpty() ? "surjective" : "not surjective, missed " + show(missed)));
    }

    static long power(long b, int e) {
        long r = 1;
        for (int i = 0; i < e; i++) r *= b;
        return r;
    }

    static long choose(int n, int k) {
        long r = 1;
        for (int i = 1; i <= k; i++) r = r * (n - k + i) / i;
        return r;
    }

    // Brute force over all n^m functions {0..m-1} -> {0..n-1}
    static int[] classify(int m, int n) {
        int total = (int) power(n, m), injective = 0, surjective = 0, bijective = 0;
        for (int code = 0; code < total; code++) {
            Set<Integer> image = new HashSet<>();
            for (int x = 0, c = code; x < m; x++, c /= n) image.add(c % n);
            boolean inj = image.size() == m, surj = image.size() == n;
            if (inj) injective++;
            if (surj) surjective++;
            if (inj && surj) bijective++;
        }
        return new int[] {total, injective, surjective, bijective};
    }

    static void countSurjections(int m, int n) {
        int[] c = classify(m, n);
        // Inclusion-exclusion: subtract functions that miss at least one of the n targets
        long formula = 0;
        for (int i = 0; i <= n; i++) formula += (i % 2 == 0 ? 1 : -1) * choose(n, i) * power(n - i, m);
        System.out.println("surjections from a " + m + "-set onto a " + n + "-set: " + c[2] + " of " + c[0]
                + " (inclusion-exclusion: " + formula + ")");
    }

    public static void main(String[] args) {
        report("h(x) = x mod 3, {0..5} -> {0, 1, 2}", x -> x % 3, 6, 3);
        report("k(x) = 2x, {0, 1, 2} -> {0..5}", x -> 2 * x, 3, 6);
        countSurjections(4, 3);
        countSurjections(2, 3); // too few inputs to cover every output
        int[] same = classify(3, 3);
        System.out.println("3-set to 3-set: " + same[1] + " injective, " + same[2] + " surjective, " + same[3]
                + " bijective");
    }
}

