#include <iostream>
#include <set>
#include <string>

std::string show(const std::set<int>& s) {
    std::string out = "{";
    for (int x : s) out += (out.size() > 1 ? ", " : "") + std::to_string(x);
    return out + "}";
}

void report(const std::string& label, const std::function<int(int)>& f, int domainSize, int codomainSize) {
    std::set<int> image, missed;
    for (int x = 0; x < domainSize; x++) image.insert(f(x));
    for (int y = 0; y < codomainSize; y++)
        if (!image.count(y)) missed.insert(y);
    std::cout << label << ": image " << show(image) << " -> "
              << (missed.empty() ? "surjective" : "not surjective, missed " + show(missed)) << "\n";
}

long long power(long long b, int e) {
    long long r = 1;
    for (int i = 0; i < e; i++) r *= b;
    return r;
}

long long choose(int n, int k) {
    long long r = 1;
    for (int i = 1; i <= k; i++) r = r * (n - k + i) / i;
    return r;
}

// Brute force over all n^m functions {0..m-1} -> {0..n-1}: {total, injective, surjective, bijective}
std::array<int, 4> classify(int m, int n) {
    std::array<int, 4> counts{static_cast<int>(power(n, m)), 0, 0, 0};
    for (int code = 0; code < counts[0]; code++) {
        std::set<int> image;
        for (int x = 0, c = code; x < m; x++, c /= n) image.insert(c % n);
        bool inj = static_cast<int>(image.size()) == m, surj = static_cast<int>(image.size()) == n;
        if (inj) counts[1]++;
        if (surj) counts[2]++;
        if (inj && surj) counts[3]++;
    }
    return counts;
}

void countSurjections(int m, int n) {
    auto c = classify(m, n);
    // Inclusion-exclusion: subtract functions that miss at least one of the n targets
    long long formula = 0;
    for (int i = 0; i <= n; i++) formula += (i % 2 == 0 ? 1 : -1) * choose(n, i) * power(n - i, m);
    std::cout << "surjections from a " << m << "-set onto a " << n << "-set: " << c[2] << " of " << c[0]
              << " (inclusion-exclusion: " << formula << ")\n";
}

int main() {
    report("h(x) = x mod 3, {0..5} -> {0, 1, 2}", [](int x) { return x % 3; }, 6, 3);
    report("k(x) = 2x, {0, 1, 2} -> {0..5}", [](int x) { return 2 * x; }, 3, 6);
    countSurjections(4, 3);
    countSurjections(2, 3);  // too few inputs to cover every output
    auto same = classify(3, 3);
    std::cout << "3-set to 3-set: " << same[1] << " injective, " << same[2] << " surjective, " << same[3]
              << " bijective\n";
}

